type Analytics = { pageViews: number; visitors: number; bounceRate: number }
type Notification = { id: number; message: string; read: boolean }
type Settings = { theme: string; language: string; emailNotifications: boolean }

// Server-side fetch needs an absolute URL, so resolve the /api/* paths against the app's origin
const baseUrl = process.env.NEXT_PUBLIC_BASE_URL ?? 'http://localhost:3000'

// Parallel data fetching, same as getParallelData in page.tsx
async function getDashboardData() {
  try {
    const [analytics, notifications, settings]: [Analytics, Notification[], Settings] =
      await Promise.all([
        fetch(`${baseUrl}/api/analytics`).then((r) => r.json()),
        fetch(`${baseUrl}/api/notifications`).then((r) => r.json()),
        fetch(`${baseUrl}/api/settings`).then((r) => r.json()),
      ])

    return { analytics, notifications, settings }
  } catch {
    // Return mock data for build time
    return {
      analytics: { pageViews: 1000, visitors: 250, bounceRate: 0.42 },
      notifications: [{ id: 1, message: 'Welcome to your dashboard', read: false }],
      settings: { theme: 'light', language: 'en', emailNotifications: true },
    }
  }
}

// Start the requests early so they run alongside the parent's data fetching.
// Identical fetch calls are memoized, so Dashboard reuses these in-flight requests.
export const preload = () => {
  void getDashboardData()
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData()
  const unread = notifications.filter((n) => !n.read).length

  return (
    <div>
      <h2>Analytics</h2>
      <p>Page views: {analytics.pageViews}</p>
      <p>Visitors: {analytics.visitors}</p>
      <p>Bounce rate: {Math.round(analytics.bounceRate * 100)}%</p>

      <h2>Notifications ({unread} unread)</h2>
      <ul>
        {notifications.map((n) => (
          <li key={n.id}>
            {n.read ? n.message : <strong>{n.message}</strong>}
          </li>
        ))}
      </ul>

      <h2>Settings</h2>
      <p>Theme: {settings.theme}</p>
      <p>Language: {settings.language}</p>
      <p>Email notifications: {settings.emailNotifications ? 'On' : 'Off'}</p>
    </div>
  )
}

